// Variantes de questions (14.11, « les questions doivent absolument être variées ») : formes supplémentaires
// par notion et par niveau, tirées au hasard avec la forme d'origine (Engine.build). VAR[id][niveau] = [() => question, …].
// Mêmes conventions que les générateurs : QV (valeur), QX (expression), M(…) pour les formules, sol = corrigé.
// Une forme = un énoncé différent (inverse, contexte, autre structure), pas seulement d'autres nombres.
const VAR = {};
const V = (id, lv, ...fns) => { (VAR[id] = VAR[id] || {})[lv] = fns; };
const V34 = (id, ...fns) => { V(id, 3, ...fns); V(id, 4, ...fns); };
const r6 = (v) => Math.round(v * 1e6) / 1e6;
const chf = (v) => (+v).toFixed(2).replace(".", "{,}"); // montant en TeX : 3{,}50
const dT = (v) => decTxt(r6(v)); // décimal en texte simple : 2,5
const d1 = (a, b) => R.int(Math.round(a * 10), Math.round(b * 10)) / 10;
const d2 = (a, b) => R.int(Math.round(a * 100), Math.round(b * 100)) / 100;
const nonInt = (f) => { let v; do v = f(); while (Number.isInteger(v)); return v; };
const mille = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, "'");
// Retire jusqu'à obtenir une question non triviale (même filtre que le moteur), 20 essais au plus.
const clean = (f) => { let q; for (let i = 0; i < 20; i++) { q = f(); if (!trivialQ(q, 0)) break; } return q; };
const NTH = ["", "", "demi", "tiers", "quart", "cinquième", "sixième", "septième", "huitième"];
const MULT = ["", "", "le double", "le triple", "le quadruple", "le quintuple"];

// ======================= 9e =======================
// --- Écritures décimales ---
V("decread", 2,
  () => { const u = R.int(2, 9), di = R.int(1, 9), mi = R.int(1, 9), v = r6(u + di / 10 + mi / 1000);
    return QV("Écris en nombre décimal : " + M(u + " + \\frac{" + di + "}{10} + \\frac{" + mi + "}{1000}") + ".", v, M(u + " + \\frac{" + di + "}{10} + \\frac{" + mi + "}{1000} = " + dec(v)) + " (pas de centième : on écrit 0).", { traps: [TRAP(r6(u + di / 10 + mi / 100), "Il n'y a pas de centièmes : on écrit 0 à leur place, puis les millièmes.")], plain: true, guide: [GS("Chiffre des centièmes (il n'y en a pas) ?", 0, "0 : on l'écrit pour garder la place."), GS("Le nombre ?", v, M(dec(v)) + ".")] }); },
  () => { const dz = R.int(1, 9), u = R.int(1, 9), ce = R.int(1, 9), v = r6(dz * 10 + u + ce / 100);
    return QV("Écris en nombre décimal : " + dz + (dz > 1 ? " dizaines, " : " dizaine, ") + u + " unité" + (u > 1 ? "s" : "") + " et " + ce + " centième" + (ce > 1 ? "s" : "") + ".", v, M(dz * 10 + " + " + u + " + \\frac{" + ce + "}{100} = " + dec(v)) + " (pas de dixième : on écrit 0).", { traps: [TRAP(r6(dz * 10 + u + ce / 10), "Il n'y a pas de dixièmes : on écrit 0 à leur place, puis les centièmes.")], plain: true, guide: [GS("Chiffre des dixièmes (il n'y en a pas) ?", 0, "0 : on l'écrit pour garder la place."), GS("Le nombre ?", v, M(dec(v)) + ".")] }); },
  () => { const x = r6(R.int(1, 9) + R.int(11, 89) / 100), k = R.int(2, 9), v = r6(x + k / 100);
    return QV("Quel nombre obtient-on en ajoutant " + k + " centièmes à " + M(dec(x)) + " ?", v, M(dec(x) + " + 0{,}0" + k + " = " + dec(v)) + ".", { traps: [TRAP(r6(x + k / 10), "Des centièmes, pas des dixièmes : " + k + " centièmes s'écrivent " + M("0{,}0" + k) + "."), TRAP(r6(x + k / 1000), "Les centièmes sont le 2e chiffre après la virgule, pas le 3e.")], plain: true, guide: [GS(k + " centièmes en nombre décimal ?", k / 100, M("0{,}0" + k) + "."), GS("Résultat ?", v, M(dec(x) + " + 0{,}0" + k + " = " + dec(v)) + ".")] }); },
);
V34("deccomp",
  () => { const a = R.int(11, 89) / 10, k = 1; return QV("Combien y a-t-il de nombres à deux chiffres après la virgule strictement compris entre " + M(dec(a)) + " et " + M(dec(r6(a + k / 10))) + " ?", 10 * k - 1, "De " + M(dec(r6(a + 0.01))) + " à " + M(dec(r6(a + k / 10 - 0.01))) + " : il y en a " + (10 * k - 1) + ".", { guide: [GS("Premier nombre à deux décimales après " + M(dec(a)) + " ?", r6(a + 0.01), M(dec(r6(a + 0.01))) + "."), GS("Dernier avant " + M(dec(r6(a + 0.1))) + " ?", r6(a + 0.09), M(dec(r6(a + 0.09))) + "."), GS("De " + dT(r6(a + 0.01)) + " à " + dT(r6(a + 0.09)) + " : combien de nombres ?", 9, "9 nombres.")], traps: [TRAP(10 * k + 1, "Strictement compris : les deux bornes ne comptent pas."), TRAP(10 * k, "Strictement compris : les deux bornes ne comptent pas.")] }); },
  () => { const a = r6(R.int(101, 989) / 100); return QV("Quel est le plus petit nombre à deux chiffres après la virgule strictement plus grand que " + M(dec(a)) + " ?", r6(a + 0.01), "On ajoute un centième : " + M(dec(r6(a + 0.01))) + ".", { guide: [GS("Un centième en nombre décimal ?", 0.01, M("0{,}01") + "."), GS("Ajoute-le à " + M(dec(a)) + " : ?", r6(a + 0.01), M(dec(r6(a + 0.01))) + ".")], traps: [TRAP(r6(a + 0.1), "On ajoute un centième (deuxième chiffre après la virgule), pas un dixième."), TRAP(r6(a + 0.001), "Le nombre doit avoir deux chiffres après la virgule.")], plain: true }); },
);
// --- Ordres de grandeur ---
V("ordgr", 1,
  () => { const a = R.int(4, 9) * 1000 + R.int(110, 390), b = R.int(1, 3) * 1000 + R.int(110, 390), A = Math.round(a / 1000) * 1000, B = Math.round(b / 1000) * 1000;
    return QV("Estime " + M(a + " - " + b) + " en arrondissant chaque nombre au millier.", A - B, M(a + " \\approx " + A) + " et " + M(b + " \\approx " + B) + " : " + M(A + " - " + B + " = " + (A - B)) + "."); },
  () => { const a = R.int(21, 59) * 10 - R.int(1, 4), b = R.int(4, 9) * 10 + R.int(1, 4), A = Math.round(a / 10) * 10, B = Math.round(b / 10) * 10;
    return QV("Un vélo coûte " + M(a) + " CHF et un casque " + M(b) + " CHF. Estime le prix total en arrondissant chaque prix à la dizaine.", A + B, M(a + " \\approx " + A) + " et " + M(b + " \\approx " + B) + " : environ " + M(A + B) + " CHF."); },
);
V("ordgr", 2,
  () => { const p = d2(1.81, 1.98), L = R.int(3, 7) * 10 + R.int(1, 3), Lr = Math.round(L / 10) * 10;
    return QV("L'essence coûte " + M(dec(p)) + " CHF le litre. Estime le prix de " + M(L) + " litres en arrondissant le prix à l'unité et la quantité à la dizaine.", 2 * Lr, M(dec(p) + " \\approx 2") + " et " + M(L + " \\approx " + Lr) + " : environ " + M(2 * Lr) + " CHF."); },
  () => { const a = R.int(3, 9), b = R.int(3, 9) * 100, x = r6(a + R.pick([-0.2, -0.1, 0.1, 0.2, 0.3])), y = b + R.pick([-30, -20, 20, 30, 40]);
    return QV("Estime " + M(dec(x) + " \\cdot " + y) + " en arrondissant le premier nombre à l'unité et le second à la centaine.", a * b, M(dec(x) + " \\approx " + a) + " et " + M(y + " \\approx " + b) + " : " + M(a + " \\cdot " + b + " = " + a * b) + "."); },
);
V34("ordgr",
  () => { const d = R.pick([30, 40, 50, 60, 70, 80]), q = R.pick([20, 30, 40, 60, 70, 90]), A = d * q, a = A + R.pick([-30, -20, 20, 30]) + R.pick([-1, 1]) * R.int(1, 9), b = d + R.pick([-3, -2, 2, 3]);
    return QV("Estime " + M(a + " : " + b) + " en arrondissant le premier nombre à la centaine et le second à la dizaine.", q, M(a + " \\approx " + A) + " et " + M(b + " \\approx " + d) + " : " + M(A + " : " + d + " = " + q) + "."); },
  () => { const d = R.pick([20, 30, 40, 50]), q = R.pick([30, 40, 60, 70, 80]), A = d * q, a = A + R.pick([-40, -20, 20, 30]) + R.int(1, 9), b = d + R.pick([-2, -1, 1, 2]);
    return QV("Une association récolte " + M(a) + " CHF, à partager entre " + M(b) + " projets. Estime la part de chacun en arrondissant la somme à la centaine et le nombre de projets à la dizaine.", q, M(a + " \\approx " + A) + " et " + M(b + " \\approx " + d) + " : environ " + M(A + " : " + d + " = " + q) + " CHF."); },
);
// --- Additions et soustractions de décimaux ---
V("decadd", 1,
  () => { const a = d1(2, 9), c = r6(a + nonInt(() => d1(2, 9))); return QV("Complète : " + M(dec(a) + " + \\ ? = " + dec(c)), r6(c - a), M(dec(c) + " - " + dec(a) + " = " + dec(r6(c - a))) + "."); },
  () => { const a = d2(3, 15), b = d2(1, 9); return QV("Lina a " + M(chf(a)) + " CHF dans sa tirelire. Sa grand-mère lui donne " + M(chf(b)) + " CHF. Combien a-t-elle maintenant (en CHF) ?", r6(a + b), M(chf(a) + " + " + chf(b) + " = " + chf(r6(a + b))) + " CHF."); },
);
V("decadd", 2,
  () => { const L = R.int(3, 9), c = nonInt(() => d2(0.5, L - 1)); return QV("On coupe " + M(dec(c)) + " m d'un ruban de " + M(L) + " m. Quelle longueur reste-t-il (en m) ?", r6(L - c), M(L + " - " + dec(c) + " = " + dec(r6(L - c))) + " m."); },
  () => { const a = d2(2, 9), b = r6(a + nonInt(() => d2(1, 9))); return QV("De combien faut-il augmenter " + M(dec(a)) + " pour obtenir " + M(dec(b)) + " ?", r6(b - a), M(dec(b) + " - " + dec(a) + " = " + dec(r6(b - a))) + "."); },
);
V34("decadd",
  () => { const t = nonInt(() => d1(-5, 8)), u = nonInt(() => d1(2, 9)), v = nonInt(() => d1(3, 12)), f = r6(t + u - v); return QV("Le matin, il fait " + M(dec(t)) + " °C. La température monte de " + M(dec(u)) + " °C, puis baisse de " + M(dec(v)) + " °C. Quelle température fait-il alors (en °C) ?", f, M(dec(t) + " + " + dec(u) + " - " + dec(v) + " = " + dec(f)) + " °C."); },
  () => { const a = R.int(20, 50), b = d2(2, 9), c = d2(1, 9); return QV("Calcule : " + M(a + " - (" + dec(b) + " + " + dec(c) + ")"), r6(a - b - c), "Parenthèse d'abord : " + M(dec(b) + " + " + dec(c) + " = " + dec(r6(b + c))) + ", puis " + M(a + " - " + dec(r6(b + c)) + " = " + dec(r6(a - b - c))) + "."); },
);
// --- Multiplier et diviser par 10, 100… ---
V("dec10", 1,
  () => { const p = R.pick([10, 100, 1000]), x = r6(R.int(101, 9899) / 1000); return QV("Par quel nombre faut-il multiplier " + M(dec(x)) + " pour obtenir " + M(dec(r6(x * p))) + " ?", p, "La virgule a avancé de " + (String(p).length - 1) + " rang" + (p > 10 ? "s" : "") + " : on a multiplié par " + M(p) + ".", { guide: [GS("De combien de rangs la virgule a-t-elle avancé ?", (String(p).length - 1), (String(p).length - 1) + " rang(s)."), GS("On a donc multiplié par ?", p, M(p) + ".")], traps: [TRAP(p / 10, "Compte les rangs dont la virgule a avancé : " + (String(p).length - 1) + "."), TRAP(p * 10, "Compte les rangs dont la virgule a avancé : " + (String(p).length - 1) + "."), TRAP(1 / p, "Le nombre a grandi : on a multiplié par " + p + ", pas par " + dec(1 / p) + ".")], plain: true }); },
  () => { const p = R.pick([10, 100, 1000]), y = R.int(12, 9800); return QV("Complète : " + M("? \\cdot " + p + " = " + y), r6(y / p), M(y + " : " + p + " = " + dec(r6(y / p))) + ".", { guide: [GS("Pour retrouver le nombre, on fait l'opération inverse : on divise " + y + " par " + p + ". De combien de rangs la virgule recule-t-elle ?", (String(p).length - 1), (String(p).length - 1) + " rang(s)."), GS("Nombre cherché ?", r6(y / p), M(dec(r6(y / p))) + ".")], traps: [TRAP(y * p, "Pour retrouver le nombre de départ, on divise par " + p + "."), TRAP(r6(y / p * 10), "La virgule recule de " + (String(p).length - 1) + " rang" + (p > 10 ? "s" : "") + ".")], plain: true }); },
);
V("dec10", 2,
  () => { const p = R.pick([10, 100, 1000]), x = R.int(13, 987); return QV("Complète : " + M("? : " + p + " = " + dec(r6(x / p))), x, M(dec(r6(x / p)) + " \\cdot " + p + " = " + x) + ".", { guide: [GS("Opération inverse : on multiplie " + dec(r6(x / p)) + " par " + p + ". De combien de rangs la virgule avance-t-elle ?", (String(p).length - 1), (String(p).length - 1) + " rang(s)."), GS("Nombre cherché ?", x, M(x) + ".")], traps: [TRAP(r6(x / p / p), "Pour retrouver le nombre de départ, on multiplie par " + p + "."), TRAP(x * 10, "La virgule avance de " + (String(p).length - 1) + " rang" + (p > 10 ? "s" : "") + ".")], plain: true }); },
  () => { const p = R.pick([100, 1000]), x = R.int(21, 980); return QV("Un paquet de " + M(mille(p)) + " feuilles pèse " + M(x) + " g. Combien pèse une feuille (en g) ?", r6(x / p), M(x + " : " + p + " = " + dec(r6(x / p))) + " g.", { guide: [GS("Une feuille = " + M(x + " : " + p) + ". De combien de rangs la virgule recule-t-elle ?", (String(p).length - 1), (String(p).length - 1) + " rangs."), GS("Masse d'une feuille (en g) ?", r6(x / p), M(dec(r6(x / p))) + " g.")], traps: [TRAP(x * p, "Une feuille pèse beaucoup moins que le paquet : on divise."), TRAP(r6(x / p * 10), "La virgule recule de " + (String(p).length - 1) + " rangs.")], plain: true }); },
);
// --- Multiplier des décimaux ---
V("decmul", 1,
  () => { const p = nonInt(() => d2(1.1, 4.9)), n = R.int(3, 9); return QV("Un stylo coûte " + M(chf(p)) + " CHF. Combien coûtent " + M(n) + " stylos (en CHF) ?", r6(p * n), M(n + " \\cdot " + chf(p) + " = " + chf(r6(p * n))) + " CHF."); },
  () => { const x = nonInt(() => d1(1.1, 9.9)), k = R.int(2, 4); return QV("Calcule " + MULT[k] + " de " + M(dec(x)) + ".", r6(k * x), M(k + " \\cdot " + dec(x) + " = " + dec(r6(k * x))) + "."); },
);
V("decmul", 2,
  () => { const p = R.pick([2.5, 4.5, 6.5, 12.5, 3.2, 1.8]), L = nonInt(() => d1(1.2, 3.8)); return QV("Un tissu coûte " + M(chf(p)) + " CHF le mètre. Combien coûtent " + M(dec(L)) + " m de ce tissu (en CHF) ?", r6(p * L), M(dec(L) + " \\cdot " + chf(p) + " = " + chf(r6(p * L))) + " CHF."); },
  () => { const a = nonInt(() => d1(1.2, 6.8)), b = nonInt(() => d1(1.2, 4.8)); return QV("Calcule l'aire d'un rectangle de " + M(dec(a)) + " m sur " + M(dec(b)) + " m (en m²).", r6(a * b), M(dec(a) + " \\cdot " + dec(b) + " = " + dec(r6(a * b))) + " m²."); },
);
V34("decmul",
  () => { const a = R.int(2, 9) / 10; return QV("Calcule l'aire d'un carré de côté " + M(dec(a)) + " m (en m²).", r6(a * a), M(dec(a) + " \\cdot " + dec(a) + " = " + dec(r6(a * a))) + " m² : le résultat est plus petit que le côté !"); },
  () => { const a = R.int(2, 9) / 10, b = R.int(2, 9) / 10; return QV("Un champ rectangulaire mesure " + M(dec(a)) + " km sur " + M(dec(b)) + " km. Quelle est son aire (en km²) ?", r6(a * b), M(dec(a) + " \\cdot " + dec(b) + " = " + dec(r6(a * b))) + " km² (deux décimales en tout)."); },
);
// --- Diviser des décimaux ---
V("decdiv", 1,
  () => { const n = R.int(3, 6), q = nonInt(() => d2(2.1, 9.9)), t = r6(n * q); return QV(M(n) + " amis partagent équitablement une dépense de " + M(chf(t)) + " CHF. Combien chacun paie-t-il (en CHF) ?", q, M(chf(t) + " : " + n + " = " + chf(q)) + " CHF."); },
  () => { const n = R.int(3, 9), q = nonInt(() => d1(1.1, 9.9)); return QV("Complète : " + M(n + " \\cdot \\ ? = " + dec(r6(n * q))), q, M(dec(r6(n * q)) + " : " + n + " = " + dec(q)) + "."); },
);
V("decdiv", 2,
  () => { const p = R.pick([0.2, 0.25, 0.4, 0.5, 0.75]), k = R.int(3, 12), L = r6(p * k); return QV("Combien de verres de " + M(dec(p)) + " L peut-on remplir avec " + M(dec(L)) + " L de jus ?", k, M(dec(L) + " : " + dec(p) + " = " + k) + " verres."); },
  () => { const p = R.pick([0.4, 0.5, 0.6, 0.8, 1.2, 1.5]), k = R.int(3, 15), L = r6(p * k); return QV("Une barre de " + M(dec(L)) + " m est coupée en morceaux de " + M(dec(p)) + " m. Combien de morceaux obtient-on ?", k, "On multiplie les deux nombres par 10 : " + M(dec(r6(L * 10)) + " : " + dec(r6(p * 10)) + " = " + k) + "."); },
);
V34("decdiv",
  () => { const m = nonInt(() => d1(1.2, 3.8)), p = nonInt(() => d1(2.1, 6.9)), t = r6(m * p); return QV(M(dec(m)) + " kg de fromage coûtent " + M(chf(t)) + " CHF. Quel est le prix d'un kilo (en CHF) ?", p, M(chf(t) + " : " + dec(m) + " = " + dec(p)) + " CHF le kilo."); },
  () => { const a = nonInt(() => d1(1.2, 4.8)), b = nonInt(() => d1(1.2, 6.8)); return QV("Complète : " + M(dec(a) + " \\cdot \\ ? = " + dec(r6(a * b))), b, M(dec(r6(a * b)) + " : " + dec(a) + " = " + dec(b)) + "."); },
);
// --- Problèmes avec des décimaux ---
V("decprob", 1,
  () => { const m = nonInt(() => d1(1.2, 4.8)), n = R.int(3, 9); return QV("Un sac de farine pèse " + M(dec(m)) + " kg. Combien pèsent " + M(n) + " sacs (en kg) ?", r6(m * n), M(n + " \\cdot " + dec(m) + " = " + dec(r6(m * n))) + " kg.", { guide: [GS("On multiplie la masse d'un sac par " + n + ". Sans virgule : " + M(Math.round(m * 10) + " \\cdot " + n) + " = ?", Math.round(m * 10) * n, M(Math.round(m * 10) * n) + "."), GS("Avec la virgule (une décimale) ?", r6(m * n), M(dec(r6(m * n))) + " kg.")], traps: [TRAP(r6(m + n), "Pour " + n + " sacs, on multiplie."), TRAP(r6(m * n * 10), "Vérifie la place de la virgule.")] }); },
  () => { const v = R.pick([0.25, 0.2, 0.33, 0.15]), n = R.int(6, 15); return QV("Un verre contient " + M(dec(v)) + " L. Quelle quantité faut-il pour remplir " + M(n) + " verres (en L) ?", r6(v * n), M(n + " \\cdot " + dec(v) + " = " + dec(r6(v * n))) + " L.", { guide: [GS("Sans virgule : " + M(Math.round(v * 100) + " \\cdot " + n) + " = ?", Math.round(v * 100) * n, M(Math.round(v * 100) * n) + "."), GS("Avec deux décimales ?", r6(v * n), M(dec(r6(v * n))) + " L.")], traps: [TRAP(r6(v + n), "Pour " + n + " verres, on multiplie."), TRAP(r6(v * n * 10), "Vérifie la place de la virgule.")] }); },
);
V("decprob", 2,
  () => { const pc = R.pick([5.5, 6, 6.5, 7]), pk = R.pick([2.8, 3.2, 3.5, 3.8]), k = R.int(4, 12), t = r6(pc + pk * k); return QV("Un taxi coûte " + M(chf(pc)) + " CHF de prise en charge, puis " + M(chf(pk)) + " CHF par kilomètre. Combien coûte une course de " + M(k) + " km (en CHF) ?", t, M(chf(pc) + " + " + k + " \\cdot " + chf(pk) + " = " + chf(t)) + " CHF.", { guide: [GS("Prix des kilomètres : " + M(k + " \\cdot " + chf(pk)) + " = ?", r6(pk * k), M(chf(r6(pk * k))) + " CHF."), GS("Plus la prise en charge (une seule fois) ?", t, M(chf(t)) + " CHF.")], traps: [TRAP(r6((pc + pk) * k), "La prise en charge ne se paie qu'une fois."), TRAP(r6(pk * k), "N'oublie pas la prise en charge.")] }); },
  () => { const s = R.pick([50, 100]), a = d2(15, 19) /* 26.11 (vraisemblance) : cinéma 15 à 19 CHF */, b = d2(4.5, 8.9), n = R.int(2, 4), t = r6(n * a + b); return QV("Tu as " + M(s) + " CHF. Tu achètes " + M(n) + " places de cinéma à " + M(chf(a)) + " CHF et un pop-corn à " + M(chf(b)) + " CHF. Combien te reste-t-il (en CHF) ?", r6(s - t), "Dépense : " + M(n + " \\cdot " + chf(a) + " + " + chf(b) + " = " + chf(t)) + ". Reste : " + M(s + " - " + chf(t) + " = " + chf(r6(s - t))) + " CHF.", { guide: [GS("Prix des " + n + " places ?", r6(n * a), M(n + " \\cdot " + chf(a) + " = " + chf(r6(n * a))) + " CHF."), GS("Dépense totale (avec le pop-corn) ?", t, M(chf(t)) + " CHF."), GS("Il reste ?", r6(s - t), M(s + " - " + chf(t) + " = " + chf(r6(s - t))) + " CHF.")], traps: [TRAP(t, "C'est la dépense ; on demande ce qui reste."), TRAP(r6(s - a - b), "Il y a " + n + " places, pas une seule.")] }); },
);
V34("decprob",
  () => { const n = R.int(3, 6), p = nonInt(() => d1(1.2, 4.5)), cut = nonInt(() => d1(0.5, 2.5)), L = r6(n * p + cut); return QV("D'une corde de " + M(dec(L)) + " m, on retire d'abord " + M(dec(cut)) + " m abîmés, puis on coupe le reste en " + M(n) + " morceaux égaux. Combien mesure chaque morceau (en m) ?", p, "Reste : " + M(dec(L) + " - " + dec(cut) + " = " + dec(r6(n * p))) + ". Morceau : " + M(dec(r6(n * p)) + " : " + n + " = " + dec(p)) + " m.", { guide: [GS("Longueur qui reste après avoir retiré la partie abîmée ?", r6(n * p), M(dec(L) + " - " + dec(cut) + " = " + dec(r6(n * p))) + " m."), GS("Un morceau : " + M(dec(r6(n * p)) + " : " + n) + " = ?", p, M(dec(p)) + " m.")], traps: [TRAP(r6(L / n), "Retire d'abord les mètres abîmés, puis partage."), TRAP(r6(n * p), "C'est la longueur restante ; on demande un morceau.")] }); },
  () => { const n = R.int(3, 5), part = d2(8, 25), carte = R.int(2, 6), cadeau = r6(part * n - carte); return QV(M(n) + " amis offrent un cadeau à " + M(chf(cadeau)) + " CHF et une carte à " + M(chf(carte)) + " CHF. Ils partagent la dépense en parts égales. Combien chacun paie-t-il (en CHF) ?", part, "Total : " + M(chf(cadeau) + " + " + chf(carte) + " = " + chf(r6(n * part))) + ". Part : " + M(chf(r6(n * part)) + " : " + n + " = " + chf(part)) + " CHF.", { guide: [GS("Dépense totale ?", r6(n * part), M(chf(cadeau) + " + " + chf(carte) + " = " + chf(r6(n * part))) + " CHF."), GS("Part de chacun : " + M(chf(r6(n * part)) + " : " + n) + " = ?", part, M(chf(part)) + " CHF.")], traps: [TRAP(r6(cadeau / n), "N'oublie pas la carte dans le total."), TRAP(r6(n * part), "C'est le total ; on demande la part de chacun.")] }); },
);
// --- Puissances ---
V("pow9", 1,
  () => { const cube = R.rand() < 0.5, e = cube ? R.int(2, 5) : R.int(3, 9), p = cube ? 3 : 2; return QV("Calcule le " + (cube ? "cube" : "carré") + " de " + M(e) + ".", e ** p, M(e + "^" + p + " = " + e ** p) + ".", { guide: [GS("Écris le produit : " + M(Array(p).fill(e).join(" \\cdot ")) + ". Le " + (cube ? "cube" : "carré") + " de " + e + " ?", e ** p, M(e + "^" + p + " = " + e ** p) + ".")], traps: [TRAP(p * e, "Une puissance n'est pas un produit par l'exposant : " + e + "^" + p + " = " + Array(p).fill(e).join(" · ") + "."), TRAP(e ** (p === 3 ? 2 : 3), cube ? "C'est le carré ; le cube a trois facteurs." : "C'est le cube ; le carré a deux facteurs.")] }); },
  () => { const a = R.int(4, 12); return QV("Quel nombre positif, élevé au carré, donne " + M(a * a) + " ?", a, M(a + "^2 = " + a * a) + ".", { guide: [GS("Essaie : quel nombre multiplié par lui-même donne " + a * a + " ?", a, M(a + " \\cdot " + a + " = " + a * a) + ".")], traps: [TRAP(a * a / 2, "La racine carrée n'est pas la moitié."), TRAP(a + 1, "Vérifie : " + (a + 1) + "² = " + (a + 1) ** 2 + ".")] }); },
);
V("pow9", 2,
  () => { const n = R.int(4, 8), big = mille(10 ** n); return QV("Écris " + M(big) + " comme une puissance de 10. Quel est l'exposant ?", n, M(big + " = 10^{" + n + "}") + " : il y a " + n + " zéros.", { guide: [GS("Compte les zéros après le 1 : combien ?", n, n + " zéros, donc " + M("10^{" + n + "}") + ".")], traps: [TRAP(n + 1, "Compte les zéros : le 1 ne compte pas."), TRAP(n - 1, "Compte tous les zéros.")] }); },
  () => { const a = R.pick([0.2, 0.3, 0.4, 0.5]), e = R.pick([2, 3]); return QV("Calcule : " + M(dec(a) + "^" + e), r6(a ** e), M(dec(a) + "^" + e + " = " + Array(e).fill(dec(a)).join(" \\cdot ") + " = " + dec(r6(a ** e))) + ".", { guide: [GS("Sans la virgule : " + M(Math.round(a * 10) + "^" + e) + " = ?", Math.round(a * 10) ** e, M(Math.round(a * 10) ** e) + "."), GS("Il y a " + e + " décimales en tout. Résultat ?", r6(a ** e), M(dec(r6(a ** e))) + ".")], traps: [TRAP(r6(a * e), "Une puissance n'est pas un produit par l'exposant."), TRAP(r6(a ** e * 10), "Compte les décimales : chaque facteur " + dec(a) + " en apporte une.")] }); },
);
V34("pow9",
  () => { const a = R.int(2, 4), b = R.int(2, 3), x = R.int(2, 5), v = (a + x) ** 2 - b ** 3; return QV("Calcule : " + M("(" + a + " + " + x + ")^2 - " + b + "^3"), v, M((a + x) + "^2 - " + b + "^3 = " + (a + x) ** 2 + " - " + b ** 3 + " = " + v) + ".", { guide: [GS("Parenthèse d'abord : " + M(a + " + " + x) + " = ?", a + x, M(a + x) + "."), GS(M((a + x) + "^2") + " = ?", (a + x) ** 2, M((a + x) ** 2) + "."), GS(M(b + "^3") + " = ?", b ** 3, M(b ** 3) + "."), GS("Résultat ?", v, M((a + x) ** 2 + " - " + b ** 3 + " = " + v) + ".")], traps: [TRAP(a * a + x * x - b ** 3, "(" + a + " + " + x + ")² n'est pas " + a + "² + " + x + "² : calcule d'abord la parenthèse."), TRAP((a + x) * 2 - b * 3, "Une puissance n'est pas un produit par l'exposant.")] }); },
  () => { let k, a, e, b, v; do { k = R.int(2, 5); a = R.int(2, 3); e = R.int(3, 4); b = R.int(2, 6); v = k * a ** e - b * b; } while (Math.abs(v) < 2); return QV("Calcule : " + M(k + " \\cdot " + a + "^" + e + " - " + b + "^2"), v, "Puissances d'abord : " + M(k + " \\cdot " + a ** e + " - " + b * b + " = " + v) + ".", { guide: [GS("Puissances d'abord : " + M(a + "^" + e) + " = ?", a ** e, M(a ** e) + "."), GS(M(b + "^2") + " = ?", b * b, M(b * b) + "."), GS("Puis " + M(k + " \\cdot " + a ** e) + " = ?", k * a ** e, M(k * a ** e) + "."), GS("Résultat ?", v, M(k * a ** e + " - " + b * b + " = " + v) + ".")], traps: [TRAP((k * a) ** e - b * b, "La puissance passe avant la multiplication : " + a + "^" + e + " d'abord."), TRAP(k * a * e - 2 * b, "Une puissance n'est pas un produit par l'exposant.")] }); },
);
// --- Priorités ---
V("prio", 1,
  () => { const a = R.int(3, 9), b = R.int(2, 9), c = R.int(a * b + 2, 80); return QV("Calcule : " + M(c + " - " + a + " \\cdot " + b), c - a * b, M(c + " - " + a * b + " = " + (c - a * b)) + " : la multiplication d'abord."); },
  () => { const b = R.int(2, 9), q = R.int(2, 9), a = R.int(3, 20); return QV("Calcule : " + M(a + " + " + b * q + " : " + b), a + q, M(a + " + " + q + " = " + (a + q)) + " : la division d'abord."); },
);
V("prio", 2,
  () => { const a = R.int(2, 9), b = R.int(2, 9), c = R.int(2, 6), d = R.int(2, Math.min(20, (a + b) * c - 2)); return QV("Calcule : " + M("(" + a + " + " + b + ") \\cdot " + c + " - " + d), (a + b) * c - d, M((a + b) + " \\cdot " + c + " - " + d + " = " + (a + b) * c + " - " + d + " = " + ((a + b) * c - d)) + "."); },
  () => { const b = R.int(1, 5), c = R.int(1, 5), s = b + c, q = R.int(2, 9), e = R.int(2, 15); return QV("Calcule : " + M(s * q + " : (" + b + " + " + c + ") + " + e), q + e, M(s * q + " : " + s + " + " + e + " = " + q + " + " + e + " = " + (q + e)) + "."); },
);
V34("prio",
  () => { const a = R.int(30, 90), b = R.int(5, 9), c = R.int(2, 4), v = a - (b - c) ** 2; return QV("Calcule : " + M(a + " - (" + b + " - " + c + ")^2"), v, M(a + " - " + (b - c) + "^2 = " + a + " - " + (b - c) ** 2 + " = " + v) + "."); },
  () => { let a, b, s, j, k, m; do { a = R.int(1, 4); b = R.int(1, 4); s = (a + b) ** 2; j = R.int(3, 9); k = R.int(1, j - 2); m = j * s; } while (a === b || [a, b, k].includes(j - k)); return QV("Calcule : " + M(m + " : (" + a + " + " + b + ")^2 - " + k), j - k, M(m + " : " + (a + b) + "^2 - " + k + " = " + m + " : " + s + " - " + k + " = " + j + " - " + k + " = " + (j - k)) + "."); },
);
// --- Traduire une phrase en calcul ---
V("tradexpr", 2,
  () => { const a = R.int(3, 9), b = R.int(2, 8), c = R.int(2, 6); return QV("Calcule le produit de la somme de " + a + " et " + b + " par " + c + ".", (a + b) * c, M("(" + a + " + " + b + ") \\cdot " + c + " = " + (a + b) * c) + "."); },
  () => { const c = R.int(2, 6), q = R.int(3, 9), b = R.int(2, 9), a = c * q + b; return QV("Calcule le quotient de la différence de " + a + " et " + b + " par " + c + ".", q, M("(" + a + " - " + b + ") : " + c + " = " + (a - b) + " : " + c + " = " + q) + "."); },
  () => { const a = R.int(3, 9), b = R.int(3, 9); return QV("Calcule la somme du triple de " + a + " et du double de " + b + ".", 3 * a + 2 * b, M("3 \\cdot " + a + " + 2 \\cdot " + b + " = " + (3 * a + 2 * b)) + "."); },
);
V34("tradexpr",
  () => { const a = R.int(3, 5), b = R.int(2, Math.min(6, Math.floor(Math.sqrt(a ** 3 - 2)))); return QV("Calcule le cube de " + a + ", diminué du carré de " + b + ".", a ** 3 - b * b, M(a + "^3 - " + b + "^2 = " + a ** 3 + " - " + b * b + " = " + (a ** 3 - b * b)) + "."); },
  () => { const a = R.pick([4, 6, 8, 10, 12]), b = R.int(2, 9); return QV("Calcule la moitié du carré de " + a + ", augmentée de " + b + ".", (a * a) / 2 + b, M("\\frac{" + a + "^2}{2} + " + b + " = " + (a * a) / 2 + " + " + b + " = " + ((a * a) / 2 + b)) + "."); },
);
// --- Durées ---
V("utemps", 2,
  () => { const h1 = R.int(1, 3), m1 = R.int(15, 55), h2 = R.int(1, 2), m2 = R.int(20, 55), t = h1 * 60 + m1 + h2 * 60 + m2; return QV("Une randonnée : la montée dure " + h1 + " h " + m1 + " min, la descente " + h2 + " h " + m2 + " min. Quelle est la durée totale, en minutes ?", t, M(h1 * 60 + m1 + " + " + (h2 * 60 + m2) + " = " + t) + " min."); },
  () => { const n = R.int(3, 5), e = R.int(38, 52); return QV("Tu regardes " + M(n) + " épisodes de " + M(e) + " minutes à la suite. Combien de temps cela fait-il, en minutes ?", n * e, M(n + " \\cdot " + e + " = " + n * e) + " min, soit " + Math.floor((n * e) / 60) + " h " + ((n * e) % 60) + " min."); },
);
V34("utemps",
  () => { const hc = R.int(22, 23), mc = R.int(5, 55), hl = R.int(6, 7), ml = R.int(0, 50), avant = (24 - hc) * 60 - mc, t = avant + hl * 60 + ml; return QV("Tu te couches à " + hc + " h " + String(mc).padStart(2, "0") + " et tu te lèves à " + hl + " h " + String(ml).padStart(2, "0") + ". Combien de minutes as-tu dormi ?", t, "Jusqu'à minuit : " + avant + " min ; puis " + (hl * 60 + ml) + " min. Total : " + t + " min."); },
  () => { const mo = R.pick([15, 30, 45]), hf = R.int(17, 19), mf = R.pick([0, 10, 20, 40, 50]), t = hf * 60 + mf - (8 * 60 + mo); return QV("Un magasin ouvre à 8 h " + mo + " et ferme à " + hf + " h " + String(mf).padStart(2, "0") + ", sans pause. Pendant combien de minutes est-il ouvert ?", t, "De 8 h " + mo + " à " + hf + " h " + String(mf).padStart(2, "0") + " : " + Math.floor(t / 60) + " h " + (t % 60) + " min = " + t + " min."); },
);
// --- Angles ---
V("angtype", 1,
  () => { const a = R.int(14, 76); return QV("Un angle droit est partagé en deux angles. L'un mesure " + a + "°. Combien mesure l'autre (en degrés) ?", 90 - a, M("90° - " + a + "° = " + (90 - a) + "°") + ".", { guide: [GS("Un angle droit mesure combien de degrés ?", 90, "90°."), GS("L'autre angle : " + M("90° - " + a + "°") + " = ?", 90 - a, M((90 - a) + "°") + ".")], traps: [TRAP(180 - a, "Un angle droit mesure 90°, pas 180°."), TRAP(a, "Les deux parties ont pour somme 90°.")] }); },
  () => { const k = R.int(2, 5), s = 180 / (k + 1); return QV("Un angle plat est partagé en deux angles : l'un est " + MULT[k] + " de l'autre. Combien mesure le plus grand (en degrés) ?", k * s, "Le petit compte pour 1 part, le grand pour " + k + " : " + M("180° : " + (k + 1) + " = " + s + "°") + ", le grand mesure " + M(k * s + "°") + ".", { guide: [GS("Le petit compte pour 1 part, le grand pour " + k + ". En combien de parts égales partage-t-on 180° ?", k + 1, M(k + 1) + " parts."), GS("Une part : " + M("180° : " + (k + 1)) + " = ?", s, M(s + "°") + "."), GS("Le grand angle : " + M(k + " \\cdot " + s + "°") + " = ?", k * s, M(k * s + "°") + ".")], traps: [TRAP(180 / k, "Le grand compte pour " + k + " parts et le petit pour 1 : 180° se partage en " + (k + 1) + " parts."), TRAP(s, "C'est le petit angle.")] }); },
);
V("angtype", 2,
  () => { const n = R.pick([5, 6, 8, 9, 10, 12]); return QV("Une pizza ronde est coupée en " + n + " parts égales depuis le centre. Quel angle mesure chaque part (en degrés) ?", 360 / n, M("360° : " + n + " = " + 360 / n + "°") + ".", { guide: [GS("Les " + n + " parts font le tour complet : combien de degrés ?", 360, "360°."), GS("Une part : " + M("360° : " + n) + " = ?", 360 / n, M(360 / n + "°") + ".")], traps: [TRAP(180 / n, "Le tour complet mesure 360°, pas 180°."), TRAP(100 / n, "Le tour complet mesure 360°.")] }); },
  () => { const a = R.int(70, 110), b = R.int(50, 90), c = R.int(60, 100); return QV("Quatre angles se partagent le tour complet autour d'un point. Trois d'entre eux mesurent " + a + "°, " + b + "° et " + c + "°. Combien mesure le quatrième (en degrés) ?", 360 - a - b - c, M("360° - " + a + "° - " + b + "° - " + c + "° = " + (360 - a - b - c) + "°") + ".", { guide: [GS("Somme des trois angles connus ?", a + b + c, M(a + "° + " + b + "° + " + c + "° = " + (a + b + c) + "°") + "."), GS("Quatrième : " + M("360° - " + (a + b + c) + "°") + " = ?", 360 - a - b - c, M((360 - a - b - c) + "°") + ".")], traps: [TRAP(180 - a - b - c > 0 ? 180 - a - b - c : 360 - a - b, "Le tour complet mesure 360°."), TRAP(360 - a - b, "Il faut enlever les trois angles connus.")] }); },
);
V("quadri", 2,
  () => { const k = R.int(2, 5), s = 180 / (k + 1); return QV("Dans un parallélogramme, un angle est " + MULT[k] + " de son voisin. Combien mesure le plus grand angle (en degrés) ?", k * s, "Deux angles voisins font 180° : " + M("180° : " + (k + 1) + " = " + s + "°") + ", le plus grand mesure " + M(k * s + "°") + ".", { guide: [GS("Deux angles voisins font 180°. Le petit vaut 1 part, le grand " + k + " : combien de parts en tout ?", k + 1, M(k + 1) + " parts."), GS("Une part : " + M("180° : " + (k + 1)) + " = ?", s, M(s + "°") + "."), GS("Le plus grand : " + M(k + " \\cdot " + s + "°") + " = ?", k * s, M(k * s + "°") + ".")], traps: [TRAP(s, "C'est le petit angle."), TRAP(180 / k, "Les deux angles voisins font 180° : le petit vaut 1 part, le grand " + k + " parts.")] }); },
  () => { const e = R.pick([20, 30, 40, 50, 60]); return QV("Dans un parallélogramme, un angle mesure " + e + "° de plus que son voisin. Combien mesure le plus grand (en degrés) ?", (180 + e) / 2, "Les deux font 180° : " + M("(180° + " + e + "°) : 2 = " + (180 + e) / 2 + "°") + ".", { guide: [GS("Les deux font 180°. Sans l'écart, chacun vaudrait : " + M("(180° - " + e + "°) : 2") + " = ?", (180 - e) / 2, M((180 - e) / 2 + "°") + " (le plus petit)."), GS("Le plus grand : ajoute " + e + "° ?", (180 + e) / 2, M((180 + e) / 2 + "°") + ".")], traps: [TRAP((180 - e) / 2, "C'est le plus petit."), TRAP(180 - e, "Les deux angles font 180° : on partage, puis on ajoute la moitié de l'écart.")] }); },
);
V("angtri", 1,
  () => { const a = R.int(17, 73); return QV("Un triangle est rectangle. Un de ses angles aigus mesure " + a + "°. Combien mesure l'autre angle aigu (en degrés) ?", 90 - a, M("180° - 90° - " + a + "° = " + (90 - a) + "°") + "."); },
  () => { const x = R.int(20, 45), c = 180 - 3 * x; return QV("Dans un triangle, un angle mesure " + c + "°. Des deux autres, l'un est le double de l'autre. Combien mesure le plus petit (en degrés) ?", x, "Les deux autres font " + M("180° - " + c + "° = " + 3 * x + "°") + ", soit 3 parts : " + M(3 * x + "° : 3 = " + x + "°") + "."); },
);
