V34("aire3",
  () => { const a = R.int(10, 20), b = R.int(8, 15), c = R.int(2, 5); return QV("Une pelouse rectangulaire de " + a + " m sur " + b + " m entoure un bassin carré de " + c + " m de côté. Quelle est l'aire de la pelouse (en m²) ?", a * b - c * c, M(a + " \\cdot " + b + " - " + c + "^2 = " + a * b + " - " + c * c + " = " + (a * b - c * c)) + " m².", { guide: [GS("Aire du terrain rectangulaire (en m²) ?", a * b, M(a + " \\cdot " + b + " = " + a * b) + " m²."), GS("Aire du bassin carré ?", c * c, M(c + "^2 = " + c * c) + " m²."), GS("Aire de la pelouse : terrain − bassin ?", a * b - c * c, M(a * b + " - " + c * c + " = " + (a * b - c * c)) + " m².")], traps: [TRAP(a * b, "Il faut enlever le bassin."), TRAP(a * b - 4 * c, "L'aire du bassin : côté · côté = " + c * c + " m².")] }); },
  () => { const a = R.int(6, 15), b = R.int(4, 10); return QV("Un chemin de 1 m de large fait le tour, à l'extérieur, d'un jardin rectangulaire de " + a + " m sur " + b + " m. Quelle est l'aire du chemin (en m²) ?", (a + 2) * (b + 2) - a * b, "Grand rectangle " + M((a + 2) + " \\cdot " + (b + 2) + " = " + (a + 2) * (b + 2)) + ", moins le jardin " + M(a * b) + " : " + ((a + 2) * (b + 2) - a * b) + " m².", { guide: [GS("Avec le chemin, le grand rectangle mesure " + (a + 2) + " m sur " + (b + 2) + " m (1 m de chaque côté). Son aire ?", (a + 2) * (b + 2), M((a + 2) + " \\cdot " + (b + 2) + " = " + (a + 2) * (b + 2)) + " m²."), GS("Aire du jardin ?", a * b, M(a + " \\cdot " + b + " = " + a * b) + " m²."), GS("Aire du chemin : grand rectangle − jardin ?", (a + 2) * (b + 2) - a * b, M((a + 2) * (b + 2) + " - " + a * b + " = " + ((a + 2) * (b + 2) - a * b)) + " m².")], traps: [TRAP((a + 1) * (b + 1) - a * b, "Le chemin est des deux côtés : le grand rectangle mesure " + (a + 2) + " m sur " + (b + 2) + " m."), TRAP(2 * (a + b), "Il manque les quatre coins du chemin."), TRAP((a + 2) * (b + 2), "Il faut enlever l'aire du jardin.")] }); },
);
