V("relrep", 2,
  () => { const a = R.int(3, 12), b = R.int(2, 9); return QV("Le matin, il fait " + M("-" + a) + " °C ; l'après-midi, " + M(b) + " °C. De combien de degrés la température a-t-elle monté ?", a + b, "De " + M("-" + a) + " °C à 0 °C, elle monte de " + a + " °C ; de 0 °C à " + b + " °C, de " + b + " °C. Écart : " + (a + b) + " °C.", { guide: [GS("De " + M("-" + a) + " °C à 0 °C : de combien de degrés monte-t-on ?", a, M(a) + " °C."), GS("Puis jusqu'à " + b + " °C : montée totale ?", a + b, M(a + " + " + b + " = " + (a + b)) + " °C.")], traps: [TRAP(Math.abs(b - a), "De " + (-a) + " °C à 0 °C, puis de 0 °C à " + b + " °C : on additionne."), TRAP(b, "Il faut compter aussi la montée jusqu'à 0 °C.")] }); },
  () => { const a = R.int(8, 15), b = R.int(2, a - 2); return QV("Sur une droite graduée, quelle est la distance entre les points d'abscisses " + M("-" + a) + " et " + M("-" + b) + " ?", a - b, "Les deux sont négatifs : " + M(a + " - " + b + " = " + (a - b)) + ".", { guide: [GS("Distance de " + M("-" + a) + " à 0 ?", a, M(a) + "."), GS("Distance de " + M("-" + b) + " à 0 ?", b, M(b) + "."), GS("Même côté de zéro : on soustrait. Distance ?", a - b, M(a + " - " + b + " = " + (a - b)) + ".")], traps: [TRAP(a + b, "Les deux sont du même côté de zéro : on soustrait les distances à zéro."), TRAP(b - a, "Une distance est toujours positive.")] }); },
);
V34("relrep",
  () => { const a = R.int(5, 14), h = R.int(1, Math.floor((a - 1) / 2)), b = a - 2 * h; return QV("Quel nombre est à égale distance de " + M("-" + a) + " et de " + M("-" + b) + " sur la droite graduée ?", -(a - h), "Distance " + 2 * h + ", la moitié est " + h + " : " + M("-" + a + " + " + h + " = -" + (a - h)) + ".", { guide: [GS("Distance entre les deux nombres ?", 2 * h, M(a + " - " + b + " = " + 2 * h) + "."), GS("La moitié ?", h, M(h) + "."), GS("Pars de " + M("-" + a) + " et avance de " + h + " : ?", -(a - h), M("-" + a + " + " + h + " = -" + (a - h)) + ".")], traps: [TRAP(-(a + b) / 2 === -(a - h) ? NaN : a - h, "Le milieu de deux nombres négatifs est négatif."), TRAP(-h, "C'est la moitié de la distance ; il faut partir de " + (-a) + ".")] }); },
  () => { let a, m; do { a = R.int(2, 9); m = R.int(-4, 6); } while (m === 0 || m === -a || Math.abs(2 * m + a) < 2); return QV("Le point A a pour abscisse " + M("-" + a) + ". Le milieu de [AB] a pour abscisse " + M(m) + ". Quelle est l'abscisse de B ?", 2 * m + a, "De A au milieu, on avance de " + (m + a) + ". On recommence depuis le milieu : " + M(m + " + " + (m + a) + " = " + (2 * m + a)) + ".", { guide: [GS("Écart entre A et le milieu ?", m + a, M(m + " - (-" + a + ") = " + (m + a)) + "."), GS("B est encore à cet écart après le milieu : abscisse de B ?", 2 * m + a, M(m + " + " + (m + a) + " = " + (2 * m + a)) + ".")], traps: [TRAP(m + a, "C'est l'écart entre A et le milieu ; il faut encore avancer d'autant depuis le milieu."), TRAP(2 * m - a, "Attention au signe de l'abscisse de A (" + (-a) + ").")] }); },
);
