V("volpave", 1,
  () => { const a = R.int(3, 9); return QV("Calcule le volume d'un cube d'arête " + a + " cm (en cm³).", a ** 3, M(a + "^3 = " + a ** 3) + " cm³.", { fig: FIG.cube(a + " cm"), guide: [GS("Aire d'une face : " + M(a + "^2") + " = ?", a * a, M(a * a) + " cm²."), GS("Volume : " + M(a * a + " \\cdot " + a) + " = ?", a ** 3, M(a ** 3) + " cm³.")], traps: [TRAP(3 * a, "Le volume : arête · arête · arête."), TRAP(a * a, "C'est l'aire d'une face ; le volume : arête au cube.")] }); },
  () => { const a = R.int(3, 8), b = R.int(2, 6), h = R.int(2, 9); return QV("Un pavé droit a un volume de " + a * b * h + " cm³ et une base de " + a + " cm sur " + b + " cm. Quelle est sa hauteur (en cm) ?", h, M(a * b * h + " : (" + a + " \\cdot " + b + ") = " + h) + " cm.", { guide: [GS("Aire de la base ?", a * b, M(a + " \\cdot " + b + " = " + a * b) + " cm²."), GS("Hauteur = volume : aire de la base ?", h, M(a * b * h + " : " + a * b + " = " + h) + " cm.")], traps: [TRAP(a * b * h - a * b, "On divise le volume par l'aire de la base."), TRAP(a * b * h / a, "Divise par l'aire de la base : " + a + " · " + b + " = " + a * b + " cm².")] }); },
);
V34("volpave",
  () => { const [a, b] = R.pick([[20, 25], [20, 30], [25, 40], [30, 50], [20, 50]]), h = R.int(4, 15), cm3 = a * b * h, L = cm3 / 1000; return QV("Un récipient en forme de pavé a une base de " + a + " cm sur " + b + " cm. On y verse " + M(dec(L)) + " L d'eau. Quelle hauteur l'eau atteint-elle (en cm) ?", h, M(dec(L) + " \\text{ L} = " + mille(cm3) + " \\text{ cm}^3") + " ; " + M(mille(cm3) + " : " + a * b + " = " + h) + " cm.", { guide: [GS("Volume d'eau en cm³ (1 L = 1000 cm³) ?", cm3, M(mille(cm3)) + " cm³."), GS("Aire de la base ?", a * b, M(a + " \\cdot " + b + " = " + a * b) + " cm²."), GS("Hauteur = volume : aire de la base ?", h, M(mille(cm3) + " : " + a * b + " = " + h) + " cm.")], traps: [TRAP(L * 1000 / (a + b), "On divise le volume par l'aire de la base, " + a + " · " + b + " cm²."), TRAP(cm3 / a / b * 10, "1 L = 1000 cm³ : vérifie la conversion.")] }); },
  () => { const a = R.int(2, 6), b = R.int(2, 5), h = R.pick([10, 20, 30, 40, 50]); return QV("Un carton mesure " + a + " dm sur " + b + " dm sur " + h + " cm. Quel est son volume, en litres ?", (a * b * h) / 10, h + " cm = " + h / 10 + " dm ; " + M(a + " \\cdot " + b + " \\cdot " + h / 10 + " = " + (a * b * h) / 10) + " dm³, soit " + (a * b * h) / 10 + " L.", { guide: [GS(h + " cm en dm ?", h / 10, M(h / 10) + " dm."), GS("Volume en dm³ (= litres) ?", (a * b * h) / 10, M(a + " \\cdot " + b + " \\cdot " + h / 10 + " = " + (a * b * h) / 10) + " L.")], traps: [TRAP(a * b * h, "Convertis d'abord : " + h + " cm = " + h / 10 + " dm."), TRAP((a * b * h) / 100, "Convertis d'abord : " + h + " cm = " + h / 10 + " dm.")] }); },
);
// --- Fractions ---
