// ======================= 2e passe : une 3e forme là où il n'y en avait que deux =======================
// VA ajoute des modèles à un niveau existant (le niveau 3 sert aussi au défi, niveau 4).
const VA = (id, lv, ...fns) => { for (const l of lv === 3 ? [3, 4] : [lv]) { VAR[id] = VAR[id] || {}; VAR[id][l] = (VAR[id][l] || []).concat(fns); } };
