VA("pct", 2, () => { const x = R.pick([120, 240, 360, 480]), p = R.pick([10, 15, 20, 25]); return Object.assign(QV("Un abonnement annuel coûte " + x + " CHF. Les étudiants ont " + p + " % de réduction. Combien paie un étudiant (en CHF) ?", x * (1 - p / 100), M(x + " \\cdot " + dec(1 - p / 100) + " = " + x * (1 - p / 100)) + " CHF."), { guide: [GS("Montant de la réduction : " + M(p + "\\,\\%") + " de " + M(x) + " = ?", (x * p) / 100, M("\\frac{" + p + "}{100} \\cdot " + x + " = " + (x * p) / 100) + " CHF."), GS("Prix payé ?", x * (1 - p / 100), M(x + " - " + (x * p) / 100 + " = " + x * (1 - p / 100)) + " CHF.")], traps: [TRAP((x * p) / 100, "Ça, c'est la réduction ; il faut la retirer du prix."), TRAP(x * (1 + p / 100), "C'est une réduction : le prix baisse.")] }); });
